/* runs a non-branch instruction; returns 0 if it is not one */
static int body(sh2_state *s, const dec_t *d, uint32_t pc_value)
{
    if (d->kind == K_PCREL) s->pc = pc_value;
    switch (d->name) {
    case 1: sh2_STCSR(s, d->a0); return 1;
    case 2: sh2_MOVBS0(s, d->a0, d->a1); return 1;
    case 3: sh2_MOVWS0(s, d->a0, d->a1); return 1;
    case 4: sh2_MOVLS0(s, d->a0, d->a1); return 1;
    case 5: sh2_MULL(s, d->a0, d->a1); return 1;
    case 6: sh2_CLRT(s); return 1;
    case 7: sh2_NOP(s); return 1;
    case 8: sh2_STSMACH(s, d->a0); return 1;
    case 9: sh2_MOVBL0(s, d->a0, d->a1); return 1;
    case 10: sh2_MOVWL0(s, d->a0, d->a1); return 1;
    case 11: sh2_MOVLL0(s, d->a0, d->a1); return 1;
    case 12: sh2_MAC_L(s, d->a0, d->a1); return 1;
    case 13: sh2_STCGBR(s, d->a0); return 1;
    case 14: sh2_SETT(s); return 1;
    case 15: sh2_DIV0U(s); return 1;
    case 16: sh2_STSMACL(s, d->a0); return 1;
    case 17: sh2_STCVBR(s, d->a0); return 1;
    case 18: sh2_CLRMAC(s); return 1;
    case 19: sh2_MOVT(s, d->a0); return 1;
    case 20: sh2_STSPR(s, d->a0); return 1;
    case 21: sh2_MOVLS4(s, d->a0, d->a1, d->a2); return 1;
    case 22: sh2_MOVBS(s, d->a0, d->a1); return 1;
    case 23: sh2_MOVWS(s, d->a0, d->a1); return 1;
    case 24: sh2_MOVLS(s, d->a0, d->a1); return 1;
    case 25: sh2_MOVBM(s, d->a0, d->a1); return 1;
    case 26: sh2_MOVWM(s, d->a0, d->a1); return 1;
    case 27: sh2_MOVLM(s, d->a0, d->a1); return 1;
    case 28: sh2_DIV0S(s, d->a0, d->a1); return 1;
    case 29: sh2_TST(s, d->a0, d->a1); return 1;
    case 30: sh2_AND(s, d->a0, d->a1); return 1;
    case 31: sh2_XOR(s, d->a0, d->a1); return 1;
    case 32: sh2_OR(s, d->a0, d->a1); return 1;
    case 33: sh2_CMPSTR(s, d->a0, d->a1); return 1;
    case 34: sh2_XTRCT(s, d->a0, d->a1); return 1;
    case 35: sh2_MULU(s, d->a0, d->a1); return 1;
    case 36: sh2_MULS(s, d->a0, d->a1); return 1;
    case 37: sh2_CMPEQ(s, d->a0, d->a1); return 1;
    case 38: sh2_CMPHS(s, d->a0, d->a1); return 1;
    case 39: sh2_CMPGE(s, d->a0, d->a1); return 1;
    case 40: sh2_DIV1(s, d->a0, d->a1); return 1;
    case 41: sh2_DMULU(s, d->a0, d->a1); return 1;
    case 42: sh2_CMPHI(s, d->a0, d->a1); return 1;
    case 43: sh2_CMPGT(s, d->a0, d->a1); return 1;
    case 44: sh2_SUB(s, d->a0, d->a1); return 1;
    case 45: sh2_SUBC(s, d->a0, d->a1); return 1;
    case 46: sh2_SUBV(s, d->a0, d->a1); return 1;
    case 47: sh2_ADD(s, d->a0, d->a1); return 1;
    case 48: sh2_DMULS(s, d->a0, d->a1); return 1;
    case 49: sh2_ADDC(s, d->a0, d->a1); return 1;
    case 50: sh2_ADDV(s, d->a0, d->a1); return 1;
    case 51: sh2_SHLL(s, d->a0); return 1;
    case 52: sh2_SHLR(s, d->a0); return 1;
    case 53: sh2_STSMMACH(s, d->a0); return 1;
    case 54: sh2_STCMSR(s, d->a0); return 1;
    case 55: sh2_ROTL(s, d->a0); return 1;
    case 56: sh2_ROTR(s, d->a0); return 1;
    case 57: sh2_LDSMMACH(s, d->a0); return 1;
    case 58: sh2_LDCMSR(s, d->a0); return 1;
    case 59: sh2_SHLL2(s, d->a0); return 1;
    case 60: sh2_SHLR2(s, d->a0); return 1;
    case 61: sh2_LDSMACH(s, d->a0); return 1;
    case 62: sh2_LDCSR(s, d->a0); return 1;
    case 63: sh2_MAC_W(s, d->a0, d->a1); return 1;
    case 64: sh2_DT(s, d->a0); return 1;
    case 65: sh2_CMPPZ(s, d->a0); return 1;
    case 66: sh2_STSMMACL(s, d->a0); return 1;
    case 67: sh2_STCMGBR(s, d->a0); return 1;
    case 68: sh2_CMPPL(s, d->a0); return 1;
    case 69: sh2_LDSMMACL(s, d->a0); return 1;
    case 70: sh2_LDCMGBR(s, d->a0); return 1;
    case 71: sh2_SHLL8(s, d->a0); return 1;
    case 72: sh2_SHLR8(s, d->a0); return 1;
    case 73: sh2_LDSMACL(s, d->a0); return 1;
    case 74: sh2_TAS(s, d->a0); return 1;
    case 75: sh2_LDCGBR(s, d->a0); return 1;
    case 76: sh2_SHAL(s, d->a0); return 1;
    case 77: sh2_SHAR(s, d->a0); return 1;
    case 78: sh2_STSMPR(s, d->a0); return 1;
    case 79: sh2_STCMVBR(s, d->a0); return 1;
    case 80: sh2_ROTCL(s, d->a0); return 1;
    case 81: sh2_ROTCR(s, d->a0); return 1;
    case 82: sh2_LDSMPR(s, d->a0); return 1;
    case 83: sh2_LDCMVBR(s, d->a0); return 1;
    case 84: sh2_SHLL16(s, d->a0); return 1;
    case 85: sh2_SHLR16(s, d->a0); return 1;
    case 86: sh2_LDSPR(s, d->a0); return 1;
    case 87: sh2_LDCVBR(s, d->a0); return 1;
    case 88: sh2_MOVLL4(s, d->a0, d->a1, d->a2); return 1;
    case 89: sh2_MOVBL(s, d->a0, d->a1); return 1;
    case 90: sh2_MOVWL(s, d->a0, d->a1); return 1;
    case 91: sh2_MOVLL(s, d->a0, d->a1); return 1;
    case 92: sh2_MOV(s, d->a0, d->a1); return 1;
    case 93: sh2_MOVBP(s, d->a0, d->a1); return 1;
    case 94: sh2_MOVWP(s, d->a0, d->a1); return 1;
    case 95: sh2_MOVLP(s, d->a0, d->a1); return 1;
    case 96: sh2_NOT(s, d->a0, d->a1); return 1;
    case 97: sh2_SWAPB(s, d->a0, d->a1); return 1;
    case 98: sh2_SWAPW(s, d->a0, d->a1); return 1;
    case 99: sh2_NEGC(s, d->a0, d->a1); return 1;
    case 100: sh2_NEG(s, d->a0, d->a1); return 1;
    case 101: sh2_EXTUB(s, d->a0, d->a1); return 1;
    case 102: sh2_EXTUW(s, d->a0, d->a1); return 1;
    case 103: sh2_EXTSB(s, d->a0, d->a1); return 1;
    case 104: sh2_EXTSW(s, d->a0, d->a1); return 1;
    case 105: sh2_ADDI(s, d->a0, d->a1); return 1;
    case 106: sh2_MOVBS4(s, d->a0, d->a1); return 1;
    case 107: sh2_MOVWS4(s, d->a0, d->a1); return 1;
    case 108: sh2_MOVBL4(s, d->a0, d->a1); return 1;
    case 109: sh2_MOVWL4(s, d->a0, d->a1); return 1;
    case 110: sh2_CMPIM(s, d->a0); return 1;
    case 111: sh2_MOVWI(s, d->a0, d->a1); return 1;
    case 112: sh2_MOVBSG(s, d->a0); return 1;
    case 113: sh2_MOVWSG(s, d->a0); return 1;
    case 114: sh2_MOVLSG(s, d->a0); return 1;
    case 115: sh2_MOVBLG(s, d->a0); return 1;
    case 116: sh2_MOVWLG(s, d->a0); return 1;
    case 117: sh2_MOVLLG(s, d->a0); return 1;
    case 118: sh2_MOVA(s, d->a0); return 1;
    case 119: sh2_TSTI(s, d->a0); return 1;
    case 120: sh2_ANDI(s, d->a0); return 1;
    case 121: sh2_XORI(s, d->a0); return 1;
    case 122: sh2_ORI(s, d->a0); return 1;
    case 123: sh2_TSTM(s, d->a0); return 1;
    case 124: sh2_ANDM(s, d->a0); return 1;
    case 125: sh2_XORM(s, d->a0); return 1;
    case 126: sh2_ORM(s, d->a0); return 1;
    case 127: sh2_MOVLI(s, d->a0, d->a1); return 1;
    case 128: sh2_MOVI(s, d->a0, d->a1); return 1;
    default: return 0;
    }
}

uint32_t sh2_interp_step(sh2_state *s, uint32_t a)
{
    const dec_t *d = &T[sh2_rd16(a)];
    uint32_t nxt = a + 2u, tgt;
    switch (d->kind) {
    case K_OP: case K_PCREL: case K_LDCSR: body(s, d, nxt); s->cycles += 1; return nxt;
    case K_SLEEP: s->cycles += 1; return sh2_sleep(s, a);
    case K_ILLEGAL: tgt = sh2_illegal(s, a); s->cycles += 1; return tgt;
    case K_TRAPA: tgt = sh2_trapa(s, d->a0, nxt); s->cycles += 1; return tgt;
    case K_BT: s->cycles += 1; if (s->sr & SH_T) { s->cycles += 2; return a + 4u + (uint32_t)(d->disp * 2); } return nxt;
    case K_BF: s->cycles += 1; if (!(s->sr & SH_T)) { s->cycles += 2; return a + 4u + (uint32_t)(d->disp * 2); } return nxt;
    default: break;
    }
    /* delayed branches */
    const dec_t *sd = &T[sh2_rd16(a + 2u)];
    int k = d->kind;
    if (k == K_BTS || k == K_BFS) {
        int c = (s->sr & SH_T) != 0;
        if (k == K_BFS) c = !c;
        s->cycles += 1;
        if (!c) return nxt;
        s->cycles += 1;
        tgt = a + 4u + (uint32_t)(d->disp * 2);
    } else {
        switch (k) {
        case K_BRA: s->cycles += 2; tgt = a + 4u + (uint32_t)(d->disp * 2); break;
        case K_BSR: s->cycles += 2; s->pr = a + 4u; tgt = a + 4u + (uint32_t)(d->disp * 2); break;
        case K_BRAF: tgt = a + 4u + s->r[d->a0]; s->cycles += 2; break;
        case K_BSRF: tgt = a + 4u + s->r[d->a0]; s->pr = a + 4u; s->cycles += 2; break;
        case K_JMP: tgt = s->r[d->a0]; s->cycles += 1; break;
        case K_JSR: tgt = s->r[d->a0]; s->pr = a + 4u; s->cycles += 2; break;
        case K_RTS: tgt = s->pr; s->cycles += 2; break;
        case K_RTE: tgt = sh2_rte_pop(s); s->cycles += 1; break;
        default: return sh2_unsupported(s, a);
        }
    }
    if (!body(s, sd, a + 4u)) return sh2_illegal(s, a + 2u);
    s->cycles += 1;   /* delay slot */
    return tgt;
}
